# Fixes Done For You AI section overflow on mobile: removes forced
# whiteSpace:nowrap on price text and uses responsive padding.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\Pricing.tsx"), $bytes)
Write-Host "UPDATED: src\components\Pricing.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan